    .reg .b32 %tid, %ntid, %cta_x, %cta_y;
    .reg .b64 %input, %output;
    .reg .b32 %dim1, %dim2;
    .reg .b32 %base_idx, %idx, %offset;
    .reg .f32 %sum, %val;
    .reg .f16 %h;
    .reg .b64 %addr, %saddr, %saddr2;
    .reg .pred %p1, %p2, %p3, %p4;

    // load kernel parameters
    ld.param.u64 %input, [input_ptr];
    ld.param.u64 %output, [output_ptr];

    // constants (fixed for the given model)
    mov.u32 %dim1, 4096;   // size of the reduced dimension
    mov.u32 %dim2, 4095;   // size of the remaining inner dimension

    // thread / block indices
    mov.u32 %tid,   %tid.x;
    mov.u32 %ntid,  %ntid.x;
    mov.u32 %cta_x, %ctaid.x;   // batch index
    mov.u32 %cta_y, %ctaid.y;   // inner‑dim (dim2) index

    // compute linear base index for this (batch, dim2) pair:
    // base = batch * dim1 * dim2 + dim2_idx
    mul.lo.u32 %base_idx, %cta_x, %dim1;
    mul.lo.u32 %base_idx, %base_idx, %dim2;
    add.u32 %base_idx, %base_idx, %cta_y;

    // accumulator initialization
    mov.f32 %sum, 0f00000000;

    // -----------------------------------------------------------------
    // loop over the reduced dimension (dim1) with stride = blockDim.x
    // -----------------------------------------------------------------
    mov.u32 %offset, %tid;
LOOP_START:
    setp.ge.u32 %p1, %offset, %dim1;
    @%p1 bra LOOP_END;

    // idx = base + offset * dim2
    mul.lo.u32 %idx, %offset, %dim2;
    add.u32 %idx, %idx, %base_idx;

    // address = input_ptr + idx * sizeof(half)
    cvt.u64.u32 %addr, %idx;
    mul.wide.u64 %addr, %addr, 2;
    add.u64 %addr, %input, %addr;

    // load half, convert to float, accumulate
    ld.global.f16 %h, [%addr];
    cvt.f32.f16 %val, %h;
    add.f32 %sum, %sum, %val;

    // next element in this thread's strided sequence
    add.u32 %offset, %offset, %ntid;
    bra LOOP_START;
LOOP_END:

    // -----------------------------------------------------------------
    // block‑wide reduction using shared memory (float32)
    // -----------------------------------------------------------------
    // store partial sum into shared memory
    mul.wide.u32 %saddr, %tid, 4;          // 4 bytes per float
    st.shared.b32 [%saddr], %sum;

    bar.sync 0;

    // binary tree reduction
    mov.u32 %offset, %ntid;
REDUCTION_LOOP:
    shr.u32 %offset, %offset, 1;          // offset /= 2
    setp.eq.u32 %p2, %offset, 0;
    @%p2 bra REDUCTION_DONE;

    setp.lt.u32 %p3, %tid, %offset;
    @%p3 {
        // load my value
        ld.shared.b32 %val, [%saddr];
        // load partner value
        add.u32 %idx, %tid, %offset;
        mul.wide.u32 %saddr2, %idx, 4;
        ld.shared.b32 %h, [%saddr2];
        add.f32 %val, %val, %h;
        // store back
        st.shared.b32 [%saddr], %val;
    }
    bar.sync 0;
    bra REDUCTION_LOOP;
REDUCTION_DONE:

    // -----------------------------------------------------------------
    // write final result (thread 0) to the output tensor
    // -----------------------------------------------------------------
    setp.eq.u32 %p4, %tid, 0;
    @%p4 {
        ld.shared.b32 %sum, [%saddr];          // sum = sdata[0]

        // convert back to half
        cvt.f16.f32 %h, %sum;

        // output index = batch * dim2 + dim2_idx
        mul.lo.u32 %idx, %cta_x, %dim2;
        add.u32 %idx, %idx, %cta_y;

        cvt.u64.u32 %addr, %idx;
        mul.wide.u64 %addr, %addr, 2;
        add.u64 %addr, %output, %addr;

        st.global.f16 [%addr], %h;
