    """
    Drop‑in replacement for the reference Model.
    Performs a sum reduction over the user‑specified dimension using a hand‑written PTX kernel.
    """
    def __init__(self, dim: int):
        super().__init__()
        self.dim = dim
        # Load the PTX module once
        self.ptx_mod = ptx_load(PTX_SOURCE)

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        # output shape: same as input but reduced dimension size = 1
        out_shape = list(x.shape)
        out_shape[self.dim] = 1
        out = torch.empty(out_shape, dtype=torch.float16, device=x.device)

        # Grid: one block per (batch, remaining inner index)
        # For the reference case (dim==1) we launch (batch, dim2, 1)
        if self.dim == 1:
            grid = (x.shape[0], x.shape[2], 1)
        elif self.dim == 0:
            grid = (1, x.shape[1], x.shape[2])
        else:  # dim == 2
