        # Kernel arguments: input ptr, output ptr, reduce_dim (int)
        args = [x.data_ptr(), out.data_ptr(), self.dim]

        # Launch the PTX kernel
        ptx_launch(self.ptx_mod, "sum_reduce_kernel", grid, block, args)

